export interface Report {
  generate(): string;
}
export class SalesReport implements Report {
  generate(): string {
    return "Generando informe de ventas...";
  }
}

export class InventoryReport implements Report {
  generate(): string {
    return "Generando informe de inventario...";
  }
}

export abstract class ReportFactory {
  protected abstract createReport(): Report;

  generateReport(): string {
    const report = this.createReport();
    return report.generate();
  }
}

export class SalesReportFactory extends ReportFactory {
  createReport(): Report {
    return new SalesReport();
  }
}
export class InventoryReportFactory extends ReportFactory {
  createReport(): Report {
    return new InventoryReport();
  }
}
